using System.Threading;using System;using System.Collections.Generic;using System.Linq;using RoadRush.TerrainDraft;
namespace RoadRush.TerrainDraft.Core800 {
 public readonly struct CoreCellDescriptor {public readonly int CellX,CellZ,RootX,RootZ;public readonly double MinX,MinZ,MaxX,MaxZ;public readonly string CoverageDigest,FinalBufferDigest;internal CoreCellDescriptor(int cellX,int cellZ,double minX,double minZ,double maxX,double maxZ,string coverageDigest,string finalBufferDigest){CellX=cellX;CellZ=cellZ;MinX=minX;MinZ=minZ;MaxX=maxX;MaxZ=maxZ;RootX=(int)Math.Floor((MinX+MaxX)*.5/320);RootZ=(int)Math.Floor((MinZ+MaxZ)*.5/320);CoverageDigest=coverageDigest;FinalBufferDigest=finalBufferDigest;}}
 public sealed partial class VerifiedCoreTerrain {
  static readonly object IssuerKey=new object();public const string Representation="RoadRush/ScopedCore800/1";
  public string SourceDigest{get;}public string RawDocumentDigest{get;}public string DemInputDigest{get;}public string ControlDigest{get;}public string OwnerLedgerDigest{get;}public string StructureLedgerDigest{get;}public string ScopeCoverageDigest{get;}public string FinalBufferDigest{get;}public bool SourceSubsetOnly=>true;public double MinX=>-400;public double MinZ=>-400;public double MaxX=>400;public double MaxZ=>400;
  readonly LocalTerrainMesh[] roads,terrain;readonly Dictionary<string,string[]> roadMembers;readonly Dictionary<string,SourceRoadRow[]> frames;readonly CoreCellDescriptor[] cells;readonly DerivedRoadBankDescriptor[] banks;
  // No public/JSON ctor. Issuance will occur only from the complete producer
  // after all676cell+seam+final320mbuffer verification; currently no caller.
  VerifiedCoreTerrain(object key,string sourceDigest,string rawDocumentDigest,string demInputDigest,string controlDigest,string structureLedgerDigest,Dictionary<string,SourceRoadRow[]> sourceFrames,LocalTerrainMesh[] road,LocalTerrainMesh[] ground,Dictionary<string,string[]> members,CoreCellDescriptor[] coverage,string owner,string scope,string final,DerivedRoadBankDescriptor[] derivedBanks){if(!ReferenceEquals(key,IssuerKey))throw new InvalidOperationException("Verified complete-core producer required");SourceDigest=sourceDigest;RawDocumentDigest=rawDocumentDigest;DemInputDigest=demInputDigest;ControlDigest=controlDigest;StructureLedgerDigest=structureLedgerDigest;OwnerLedgerDigest=owner;ScopeCoverageDigest=scope;FinalBufferDigest=final;roads=Clone(road);terrain=Clone(ground);roadMembers=members.ToDictionary(p=>p.Key,p=>(string[])p.Value.Clone());frames=sourceFrames.Where(p=>members.Values.SelectMany(v=>v).Contains(p.Key)).ToDictionary(p=>p.Key,p=>(SourceRoadRow[])p.Value.Clone());cells=(CoreCellDescriptor[])coverage.Clone();banks=(DerivedRoadBankDescriptor[])derivedBanks.Clone();}
  internal static VerifiedCoreTerrain IssueComplete(CoreSourceContext context,IReadOnlyList<CoreCellWork> work,CancellationToken cancellation=default){
   if(work==null||work.Count!=676||work.Any(c=>c.Proof==null||c.Failure!=null)||work.Select(c=>(c.X,c.Z)).Distinct().Count()!=676)throw new ArgumentException("Complete676actual cell capabilities required; no partial core");
   var byCell=work.ToDictionary(c=>(c.X,c.Z));foreach(var c in work){cancellation.ThrowIfCancellationRequested();var b=c.Bounds;var p=c.Proof;if(c.X< -13||c.X>12||c.Z< -13||c.Z>12||b.MinX!=Math.Max(-400,c.X*32)||b.MaxX!=Math.Min(400,(c.X+1)*32)||b.MinZ!=Math.Max(-400,c.Z*32)||b.MaxZ!=Math.Min(400,(c.Z+1)*32)||p.Scope.MinX!=b.MinX||p.Scope.MinZ!=b.MinZ||p.Scope.MaxX!=b.MaxX||p.Scope.MaxZ!=b.MaxZ||p.RawDocumentDigest!=context.RawDocumentDigest||p.SourceDigest!=context.SourceDigest||p.ControlDigest!=context.ControlDigest||p.DemInputDigest!=context.DemInputDigest||p.StructureLedgerDigest!=context.StructureLedgerDigest)throw new ArgumentException("Complete-core bounds/source binding");foreach(var n in new[]{(c.X+1,c.Z),(c.X,c.Z+1)})if(byCell.TryGetValue(n,out var other)){bool x=n.Item1!=c.X;double fixedAt=x?b.MaxX:b.MaxZ;if(!Border(c.Proof,x,fixedAt).SequenceEqual(Border(other.Proof,x,fixedAt)))throw new ArgumentException("Complete-core shared border mismatches actualfinalfloat topology/Y at"+c.X+","+c.Z);}}
   var road=work.SelectMany(c=>c.Proof.CopyFinalRoadMeshes()).ToArray();var ground=work.SelectMany(c=>c.Proof.CopyFinalTerrainMeshes()).ToArray();var all=road.Concat(ground).ToArray();if(all.Length>2048||all.Select(p=>p.Id).Distinct().Count()!=all.Length||all.Sum(p=>(long)p.XYZ.Length/3)>500000||all.Sum(p=>(long)p.Indices.Length/3)>1000000||all.Any(p=>p.XYZ.Length/3>24000||p.Indices.Length/3>48000))throw new TerrainBudgetException("ExplicitCore800buffer limits");
   var members=work.SelectMany(c=>c.Proof.CopyRoadMembers()).ToDictionary(p=>p.Key,p=>p.Value);string owner=VerifiedJoinedTerrain.Hash(string.Join("\n",work.OrderBy(c=>c.Z).ThenBy(c=>c.X).Select(c=>c.Proof.OwnerLedgerDigest)));string final=VerifiedJoinedTerrain.BufferDigest(all);var derived=DerivedBankLedger.Build(ground,new DerivedRoadBank(context.Source),final);if(derived.Length!=1)throw new ArgumentException("One explicitly measured connected derived bank component required");string bankLedger=string.Join("|",derived.Select(d=>d.Recipe+":"+d.SourceEdgeDigest+":"+string.Join(",",d.CopyTriangleReferences().Select(r=>r.PacketId+"/"+r.TriangleIndex))));string scope=VerifiedJoinedTerrain.Hash(CoreCellPreparation.Recipe+"|"+string.Join("|",work.OrderBy(c=>c.Z).ThenBy(c=>c.X).Select(c=>c.Proof.ScopeCoverageDigest))+"|"+bankLedger+"|"+final);var coverage=work.OrderBy(c=>c.Z).ThenBy(c=>c.X).Select(c=>new CoreCellDescriptor(c.X,c.Z,c.Bounds.MinX,c.Bounds.MinZ,c.Bounds.MaxX,c.Bounds.MaxZ,c.Proof.ScopeCoverageDigest,c.Proof.FinalBufferDigest)).ToArray();return new VerifiedCoreTerrain(IssuerKey,context.SourceDigest,context.RawDocumentDigest,context.DemInputDigest,context.ControlDigest,context.StructureLedgerDigest,context.Frames,road,ground,members,coverage,owner,scope,final,derived);
  }
  static string[] Border(VerifiedJoinedTerrain proof,bool x,double at){var edges=new Dictionary<string,int>();string Point(LocalTerrainMesh p,int i)=>string.Join(",",new[]{p.OriginX+p.XYZ[i*3],p.OriginY+p.XYZ[i*3+1],p.OriginZ+p.XYZ[i*3+2]}.Select(v=>v.ToString("R",System.Globalization.CultureInfo.InvariantCulture)));foreach(var p in proof.CopyFinalRoadMeshes().Concat(proof.CopyFinalTerrainMeshes()))for(int i=0;i<p.Indices.Length;i+=3)for(int k=0;k<3;k++){int a=p.Indices[i+k],b=p.Indices[i+(k+1)%3];double av=x?p.OriginX+p.XYZ[a*3]:p.OriginZ+p.XYZ[a*3+2],bv=x?p.OriginX+p.XYZ[b*3]:p.OriginZ+p.XYZ[b*3+2];if(av!=at||bv!=at)continue;string aa=Point(p,a),bb=Point(p,b),key=string.CompareOrdinal(aa,bb)<0?aa+"|"+bb:bb+"|"+aa;edges.TryGetValue(key,out int n);edges[key]=n+1;}if(edges.Values.Any(n=>n!=1))throw new ArgumentException("Core boundary edge ownership");return edges.Keys.OrderBy(v=>v,StringComparer.Ordinal).ToArray();}
  static LocalTerrainMesh[] Clone(IReadOnlyList<LocalTerrainMesh> meshes)=>meshes.Select(p=>new LocalTerrainMesh(p.Id,p.OriginX,p.OriginY,p.OriginZ,(float[])p.XYZ.Clone(),(int[])p.Indices.Clone())).ToArray();
  public LocalTerrainMesh[] CopyFinalRoadMeshes()=>Clone(roads);public LocalTerrainMesh[] CopyFinalTerrainMeshes()=>Clone(terrain);public Dictionary<string,string[]> CopyRoadMembers()=>roadMembers.ToDictionary(p=>p.Key,p=>(string[])p.Value.Clone());public Dictionary<string,SourceRoadRow[]> CopyRoadCenterFrames()=>frames.ToDictionary(p=>p.Key,p=>(SourceRoadRow[])p.Value.Clone());public CoreCellDescriptor[] CopyCells()=>(CoreCellDescriptor[])cells.Clone();public DerivedRoadBankDescriptor[] CopyDerivedRoadBanks()=>(DerivedRoadBankDescriptor[])banks.Clone();
 }
